// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;

    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(bytes32 assertionId) public {

        bool allowed;
        try c.getAssertionPolicy(assertionId) returns (BaseEscalationManager.AssertionPolicy memory policy) {
            allowed = policy.arbitrateViaEscalationManager == false;
        } catch {
            allowed = false;
        }

        assertTrue(allowed);
    }
}
